UPDATE app_settings
SET strict_rules = strict_rules || ARRAY[
'🚚 ค่าบริการเดินทาง: ฟรีเฉพาะพื้นที่ในโซนบริการ (ภายในประมาณ 60 กม. จากออฟฟิศบุญนำพา - กทม./ปริมณฑล) — **ห้ามฟันธงเองว่าฟรี/ไม่ฟรี ห้ามบอกเป็นกิโลเมตรในแชทลูกค้า** ใช้คำว่า "โซนบริการฟรี" เท่านั้น | ลูกค้าถามค่าส่ง/แจ้งสถานที่ → ตอบ "พื้นที่ [เขต/อำเภอ/จังหวัด] ขอเช็กระยะทางจากออฟฟิศก่อนนะคะ เพราะค่าบริการเดินทางฟรีครอบคลุมเฉพาะพื้นที่ในโซนบริการของบุญนำพาค่ะ เดี๋ยวแอดมินตรวจสอบแล้วแจ้งกลับอีกครั้งค่ะ" แล้วหยุด (ai_active=false) | ยกเว้นลูกค้าถามเองว่า "คิดจากอะไร/เกินกี่กิโล" จึงตอบโปร่งใสว่า "ประเมินจากระยะทางโดยประมาณจากออฟฟิศไปยังสถานที่จัดงาน โซนฟรีอยู่ในระยะประมาณ 60 กม. หากเกินอาจมีค่าเดินทางเพิ่มเติมตามระยะทางจริงค่ะ"'
]
WHERE key='ai_config';

UPDATE knowledge_base
SET content = content || E'\n\n---\n*หมายเหตุ: ฟรีค่าบริการเดินทางเฉพาะพื้นที่ในโซนบริการ (ระยะประมาณ 60 กม. จากออฟฟิศบุญนำพา) — พื้นที่นอกโซนมีค่าเดินทางเพิ่มเติมตามระยะทางจริง สอบถามแอดมินเพื่อเช็กพื้นที่ก่อนยืนยันงาน*'
WHERE id='d7db05a4-39c6-4302-a060-64ab7c456366';